  const p = document.createElement("div"); p.className = "pop"; p.style.left = Math.min(r.left, innerWidth - 280) + "px"; p.style.top = (r.bottom + 8) + "px";
  p.innerHTML = '<div class="tt">' + esc(c) + ' <button class="hb" data-say="' + esc(c) + '">🔊</button></div><div style="color:#6b7488">一个说法（chunk）。觉得你也用得上，就借进你的回答。</div><div class="mbt"><button class="pill say" id="wbBor">借进我的回答</button><button class="pill lt" data-say="' + esc(c) + '" data-slow="1">🐢 慢一点</button></div>';
